import{_ as a,o as t,c as o,am as i}from"./chunks/framework.yj4qiWdr.js";const p=JSON.parse('{"title":"Shadow Credentials to Ransomware Kill Chain","description":"","frontmatter":{},"headers":[],"relativePath":"crto/botesjuan/notes/shadow-credential-to-ransomware-storytime.md","filePath":"crto/botesjuan/notes/shadow-credential-to-ransomware-storytime.md"}'),n={name:"crto/botesjuan/notes/shadow-credential-to-ransomware-storytime.md"};function r(s,e,d,c,h,l){return t(),o("div",null,e[0]||(e[0]=[i('<h1 id="shadow-credentials-to-ransomware-kill-chain" tabindex="-1">Shadow Credentials to Ransomware Kill Chain <a class="header-anchor" href="#shadow-credentials-to-ransomware-kill-chain" aria-label="Permalink to &quot;Shadow Credentials to Ransomware Kill Chain&quot;">​</a></h1><h2 id="monday-morning" tabindex="-1">Monday morning <a class="header-anchor" href="#monday-morning" aria-label="Permalink to &quot;Monday morning&quot;">​</a></h2><p>A phishing email lands in an HR employee&#39;s inbox. She clicks a link, enters her credentials into a fake login page. The attacker now has her username and password — but her account has MFA, so the password alone is useless.</p><h2 id="foothold" tabindex="-1">Foothold <a class="header-anchor" href="#foothold" aria-label="Permalink to &quot;Foothold&quot;">​</a></h2><p>⚠️ <em>The attacker doesn&#39;t panic. He has a foothold via a macro in the attachment she also opened.</em></p><h2 id="enumeration" tabindex="-1">Enumeration <a class="header-anchor" href="#enumeration" aria-label="Permalink to &quot;Enumeration&quot;">​</a></h2><p>💬 <strong>The attacker is now a low-privilege user on her workstation.</strong></p><p>He runs BloodHound quietly in the background. The graph lights up. He finds something interesting — a service account named <code>svc_backup</code> has <strong>GenericWrite</strong> permission over a domain computer object called <code>FS01</code> (the file server).</p><p>He doesn&#39;t know the password for <code>svc_backup</code>. He doesn&#39;t need to.</p><p>👉 <strong>Here&#39;s where Shadow Credentials enters the story.</strong></p><p>Think of every computer and user account in Active Directory as having a small lockbox on it. Normally only the domain knows what key opens that lockbox — it&#39;s a secret stored as a password hash.</p><p>But Microsoft added a newer feature to AD called <strong>Key Trust</strong> (for passwordless login). It lets you attach <em>an extra key</em> to any account&#39;s lockbox. The account will accept <em>either</em> the original password <strong>or</strong> this new extra key.</p><h2 id="exploitation" tabindex="-1">Exploitation <a class="header-anchor" href="#exploitation" aria-label="Permalink to &quot;Exploitation&quot;">​</a></h2><p>The attacker abuses his <code>GenericWrite</code> permission on <code>FS01</code> to <strong>add his own key to FS01&#39;s lockbox</strong> — without touching or changing the original password. Nobody notices. No password was reset. No alerts fire.</p><p>🏢 He now has a key that the file server <code>FS01</code> will accept as proof of identity.</p><p><strong>He uses his forged key to request a Kerberos ticket for FS01.</strong></p><p>The domain controller sees a valid key, hands over a TGT (a golden pass for that machine), and the attacker extracts the <code>NTLM hash</code> of the machine account from that ticket.</p><p>Now he has the machine account credential for <code>FS01</code> — the file server — <strong>without ever logging into it, touching LSASS, or making noise.</strong></p><h2 id="persistence" tabindex="-1">Persistence <a class="header-anchor" href="#persistence" aria-label="Permalink to &quot;Persistence&quot;">​</a></h2><p><strong>Machine accounts are trusted inside the domain.</strong></p><p>🧱 With <code>FS01$</code>&#39;s credential, he performs a <strong>DCSync-style</strong> attack — machine accounts with certain roles can pull credential data from the domain controller. He dumps the <code>krbtgt</code> hash and several domain admin hashes.</p><p>He now owns the domain. Quietly. No brute force. No service creation. No loud lateral movement.</p><p><strong>Friday night. The ransomware deploys.</strong></p><h2 id="ransomware" tabindex="-1">Ransomware <a class="header-anchor" href="#ransomware" aria-label="Permalink to &quot;Ransomware&quot;">​</a></h2><p>🎯 With DA credentials he moves to every server simultaneously — backup servers first, then production. He deletes shadow copies, encrypts file shares, and drops a ransom note.</p><p>By the time IT arrives Monday morning, 3,000 file shares are encrypted and the backup server is gone.</p><hr><h2 id="why-shadow-credentials-was-the-turning-point" tabindex="-1">Why Shadow Credentials Was the Turning Point <a class="header-anchor" href="#why-shadow-credentials-was-the-turning-point" aria-label="Permalink to &quot;Why Shadow Credentials Was the Turning Point&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Stage</th><th>What happened</th></tr></thead><tbody><tr><td>Initial access</td><td>Phishing → low-priv foothold</td></tr><tr><td>Pivoting point</td><td>Found <code>GenericWrite</code> on a computer object</td></tr><tr><td><strong>Shadow Credential abuse</strong></td><td><strong>Added a rogue key to FS01 — silent, no password change</strong></td></tr><tr><td>Escalation</td><td>Used rogue key → Kerberos TGT → extracted machine NTLM hash</td></tr><tr><td>Domain compromise</td><td>Machine hash → DCSync → domain admin hashes</td></tr><tr><td>Impact</td><td>Ransomware deployed domain-wide</td></tr></tbody></table><hr><h2 id="the-key-insight-non-technical" tabindex="-1">The Key Insight (Non-Technical) <a class="header-anchor" href="#the-key-insight-non-technical" aria-label="Permalink to &quot;The Key Insight (Non-Technical)&quot;">​</a></h2><blockquote><p>Shadow Credentials is like making a <strong>copy of a building&#39;s master key</strong> by exploiting a feature designed for convenience — and nobody in the building knows an extra copy exists, because the original key was never touched and the lock was never changed.</p></blockquote><p>The defender looks for password changes, new accounts, failed logins. None of those happened. The attacker just <em>added a silent spare key to a door they had permission to modify</em> — and walked in through the back whenever they wanted.</p><hr><h2 id="detection-remediation" tabindex="-1">Detection Remediation <a class="header-anchor" href="#detection-remediation" aria-label="Permalink to &quot;Detection Remediation&quot;">​</a></h2><p>🎂 Blue team catches this via:</p><ul><li><code>Event ID 5136</code> — DS Object Modified (<code>msDS-KeyCredentialLink</code> attribute changed)</li><li>Anomalous Kerberos PKINIT requests for machine accounts</li><li>BloodHound edge: <code>AddKeyCredentialLink</code></li></ul><h2 id="forensic-investigation-questions" tabindex="-1">Forensic Investigation Questions <a class="header-anchor" href="#forensic-investigation-questions" aria-label="Permalink to &quot;Forensic Investigation Questions&quot;">​</a></h2><h3 id="identity-access" tabindex="-1">Identity &amp; Access <a class="header-anchor" href="#identity-access" aria-label="Permalink to &quot;Identity &amp; Access&quot;">​</a></h3><ul><li>🔍 Did some account have ability to write to the <code>KeyCredentialLink</code> attribute of other objects?</li><li>What key pair was created and appended by which compromised account under malicious control?</li><li>What account was compromised after initial foothold to gain write access?</li><li>Which accounts held <code>GenericWrite</code> or <code>WriteProperty</code> over computer/user objects, and were those permissions intentional or misconfigured?</li><li>Was the <code>msDS-KeyCredentialLink</code> attribute ever legitimately written to in this environment, or is any write an anomaly?</li><li>Which accounts performed PKINIT authentication (Certificate/Key Trust Kerberos) — is that normal for this environment?</li></ul><h3 id="timeline-scope" tabindex="-1">Timeline &amp; Scope <a class="header-anchor" href="#timeline-scope" aria-label="Permalink to &quot;Timeline &amp; Scope&quot;">​</a></h3><ul><li>⚠️ What is the earliest <code>Event ID 5136</code> for <code>msDS-KeyCredentialLink</code> modifications, and how far back does that pre-date the ransomware deployment?</li><li>Were multiple computer or user objects targeted with Shadow Credentials, or only one pivot point?</li><li>What is the time delta between the Shadow Credential write and the first DCSync event — was this scripted/automated?</li></ul><h3 id="lateral-movement-privilege-escalation" tabindex="-1">Lateral Movement &amp; Privilege Escalation <a class="header-anchor" href="#lateral-movement-privilege-escalation" aria-label="Permalink to &quot;Lateral Movement &amp; Privilege Escalation&quot;">​</a></h3><ul><li>Which DC processed the PKINIT TGT request, and does its KDC log (<code>Event ID 4768</code>) show certificate-based pre-auth against a machine account?</li><li>Did the <code>FS01$</code> machine account perform any unusual LDAP replication requests (<code>Event ID 4662</code> — replication GUID)?</li><li>🔥 Were any other machine accounts abused after initial DCSync, or did the attacker move straight to domain admin credentials?</li></ul><h3 id="persistence-cleanup" tabindex="-1">Persistence &amp; Cleanup <a class="header-anchor" href="#persistence-cleanup" aria-label="Permalink to &quot;Persistence &amp; Cleanup&quot;">​</a></h3><ul><li>🧩 Were any Shadow Credential keys left in place after the attack — <code>msDS-KeyCredentialLink</code> should be empty on all objects post-remediation?</li><li>Were Golden or Silver tickets generated from the dumped <code>krbtgt</code> hash — check for <code>Event ID 4769</code> with unusual encryption types (<code>0x17</code> RC4 anomaly)?</li><li>Were any new domain admin accounts or scheduled tasks created as persistence before ransomware?</li></ul><h3 id="initial-access-phishing-chain" tabindex="-1">Initial Access (Phishing Chain) <a class="header-anchor" href="#initial-access-phishing-chain" aria-label="Permalink to &quot;Initial Access (Phishing Chain)&quot;">​</a></h3><ul><li>What process spawned the macro execution — was it <code>WINWORD.EXE</code> or <code>EXCEL.EXE</code>, and what child process did it create?</li><li>💡 Does email gateway logging show the original phishing sender, and were other users targeted by the same campaign?</li></ul><hr><blockquote><p><a href="https://www.thehacker.recipes/ad/movement/kerberos/shadow-credentials" target="_blank" rel="noreferrer">Shadow Credentials - Hacker Recipes</a></p></blockquote>',50)]))}const u=a(n,[["render",r]]);export{p as __pageData,u as default};
